messages.content:
Tool response:
Tool: adjust_stock_level
Description: Adjust Stock Level
Parameters:
    {
      "type": "object",
      "properties": {
        "product_sku": {
          "type": "string",
          "description": "SKU of the product to adjust",
          "title": "Product Sku"
        },
        "warehouse_code": {
          "type": "string",
          "description": "Code of the warehouse where the product is located",
          "title": "Warehouse Code"
        },
        "bin_code": {
          "type": "string",
          "description": "Code of the bin within the warehouse where the product is located",
          "title": "Bin Code"
        },
        "adjustment_quantity": {
          "type": "integer",
          "title": "Adjustment Quantity"
        },
        "note": {
          "type": "string",
          "title": "Note"
        }
      },
      "required": [
        "product_sku",
        "warehouse_code",
        "bin_code"
      ]
    }
